// Generated by scripts/generate_data.py.
import savemap from '../data/savemap.json' with { type: 'json' };

export const CATEGORY_ORDER = savemap.categoryOrder;
export const FIELDS = savemap.fields;
export const ARRAYS = savemap.arrays;
export const ENUMS = savemap.enums;
export const GLYPHS = savemap.glyphs;
// kernel.bin: each GF's ability ids by slot (0 = empty slot), and AP cost by ability id.
export const GUARDIAN_FORCE_ABILITIES = savemap.guardianForceAbilities;
export const ABILITY_AP_COSTS = savemap.abilityApCosts;

function requireFound(found, kind, name) {
  if (found === undefined) {
    throw new Error(`The memory map has no ${kind} named "${name}" (see src/lib/fieldNames.js)`);
  }
  return found;
}

export function findArray(name) {
  return requireFound(
    ARRAYS.find((array) => array.name === name),
    'array',
    name,
  );
}

export function findField(name) {
  return requireFound(
    FIELDS.find((field) => field.name === name),
    'field',
    name,
  );
}

export function requireValue(values, name) {
  return requireFound(values[name], 'array field', name);
}
